/**
 * Generates <data>/indices/placeholder-indices.xml from the references used in
 * <data>/xml (default ./data, or --data <dir>). ONLY for development until the real index file (fulda-indices.xml)
 * is available. Delete the generated file once the real index is in place.
 *
 * Heuristic: id ending in a digit -> person, ending in "Org" -> org, else place.
 */
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs"
import { join } from "node:path"
import { dataDir } from "./data-dir"

const DATA = dataDir()
const XML_DIR = join(DATA, "xml")

// approximate coordinates of a few real places, to have something on the map
const KNOWN: Record<string, [lat: number, lon: number, type: string]> = {
    strasbourg: [48.5734, 7.7521, "city"],
    paderborn: [51.7189, 8.7575, "palace"],
    alsace: [48.3, 7.45, "region"],
    grabfeld: [50.35, 10.4, "region"],
    ostheim: [48.159, 7.369, "villa"],
    kientzheim: [48.137, 7.288, "villa"],
    ingersheim: [48.097, 7.307, "villa"],
    sigolsheim: [48.135, 7.3, "villa"],
    fuldaRiver: [50.55, 9.68, "topographic"],
}

const refs = new Set<string>()
for (const col of readdirSync(XML_DIR, { withFileTypes: true }).filter((d) => d.isDirectory())) {
    for (const f of readdirSync(join(XML_DIR, col.name)).filter((f) => f.endsWith(".xml"))) {
        const xml = readFileSync(join(XML_DIR, col.name, f), "utf8")
        for (const m of xml.matchAll(/<rs\b[^>]*\bref="([^"]+)"/g))
            m[1].split(/\s+/).forEach((r) => refs.add(r.replace(/^#/, "")))
    }
}

const label = (id: string) =>
    id
        .replace(/\d+$/, "")
        .replace(/Org$/, "")
        .replace(/^./, (c) => c.toUpperCase())
const persons: string[] = []
const places: string[] = []
const orgs: string[] = []
for (const id of [...refs].sort()) {
    if (/\d$/.test(id)) persons.push(id)
    else if (/Org$/.test(id)) orgs.push(id)
    else places.push(id)
}

// sex (TEI @sex, ISO 5218: 1 male, 2 female; left out = unknown) and alternate spellings (second <name>),
// so the person list and graph have something to show
const FEMALE = new Set(["eburhild1", "eburswind1", "ratlind1", "wulfgund1"])
const UNKNOWN = new Set(["asaph1", "vadobero1", "wilo1"])
const ALT: Record<string, string> = {
    baugulf1: "Baugolf",
    hugo1: "Hugho",
    theothard1: "Teothard",
    ratlind1: "Ratlinda",
}
const sex = (id: string) => (UNKNOWN.has(id) ? "" : ` sex="${FEMALE.has(id) ? 2 : 1}"`)
const alt = (id: string) => (ALT[id] ? `<name>${ALT[id]}</name>` : "")

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
const xml = `<?xml version="1.0" encoding="UTF-8"?>
<!-- PLACEHOLDER generated by scripts/make-placeholder-index.ts. Not real data. -->
<standOff xmlns="http://www.tei-c.org/ns/1.0" type="indicesFulda">
  <listPerson>
    <head>Persons</head>
${persons.map((id) => `    <person xml:id="${id}"${sex(id)}><persName><name>${esc(label(id))}</name>${alt(id)}</persName></person>`).join("\n")}
  </listPerson>
  <listRelation>
    <relation name="head" active="#baugulf1" passive="#fuldaOrg"/>
    <relation name="sibling" type="family" mutual="#theothard1 #eburswind1"/>
    <relation name="lord" active="#baugulf1" passive="#uto1"/>
    <relation name="spouse" type="family" mutual="#hugo1 #ratlind1"/>
    <relation name="parent" type="family" active="#hugo1 #ratlind1" passive="#odo1 #richar1"/>
    <relation name="parent" type="family" active="#theothard1" passive="#hugo1"/>
    <relation name="sibling" type="family" mutual="#odo1 #richar1"/>
    <relation name="spouse" type="family" mutual="#odo1 #wulfgund1"/>
    <relation name="parent" type="family" active="#odo1 #wulfgund1" passive="#wilo1"/>
  </listRelation>
  <listPlace>
${places
    .map((id) => {
        const k = KNOWN[id]
        // both coordinate forms seen in real data: "lat, lon" and WKT "Point(lat lon)"
        const geo = id === "strasbourg" ? `Point(${k?.[0]} ${k?.[1]})` : `${k?.[0]}, ${k?.[1]}`
        const loc = k ? `<location><geo decls="WGS84/y-x">${geo}</geo></location>` : ""
        return `    <place xml:id="${id}" type="${k?.[2] ?? "unknown"}"><placeName>${esc(label(id))}</placeName>${loc}</place>`
    })
    .join("\n")}
  </listPlace>
  <listOrg>
${orgs.map((id) => `    <org xml:id="${id}" type="monastery"><orgName>${esc(label(id))}</orgName></org>`).join("\n")}
  </listOrg>
</standOff>
`
mkdirSync(join(DATA, "indices"), { recursive: true })
writeFileSync(join(DATA, "indices", "placeholder-indices.xml"), xml)
console.log(`placeholder index: ${persons.length} persons, ${places.length} places, ${orgs.length} orgs`)
